units.text:
\Needspace{8\baselineskip}
\begin{theorem}[分位数损失的总体最优解]
  \label{thm:regression-quantile}
  若$\mathbb{E}|Y|<\infty$，分布函数为$F_Y$，则$Q(a)=\mathbb{E}[\rho_\tau(Y-a)]$的全部最小化点恰好满足
  \[
    F_Y(a-)\leq\tau\leq F_Y(a),
    \qquad F_Y(a-)=\mathbb{P}(Y<a).
  \]
\end{theorem}

